-- Expected production objects after ES import. Missing rows return false.
WITH expected(report_id, question) AS (
  VALUES
    (75, '{"type": "mcq_single", "prompt": "Как передать смысл «Когда начался дождь, мы ещё играли во дворе»?", "choices": [{"id": "a", "text": "Cuando empezó a llover, todavía jugábamos en el patio."}, {"id": "b", "text": "Cuando empezó a llover, ya no jugábamos en el patio."}, {"id": "c", "text": "Salimos a jugar al patio cuando dejó de llover."}, {"id": "d", "text": "Cuando empezamos a jugar en el patio, ya no llovía."}], "correct_answer": "a", "explanation": "Empezó называет момент начала дождя. Todavía jugábamos означает, что в этот момент игра ещё продолжалась.", "theory_block_id": "b5_theory_linking_sentences", "chapter_id": "es.grammar.past_imperfecto_contrast.build_write_childhood_memory_scene", "concept_id": "linking_background_and_event", "difficulty": 2, "id": "es.grammar.past_imperfecto_contrast.build_write_childhood_memory_scene::b5_theory_linking_sentences::q8", "signature": "eafb8a587f4832ce"}'::jsonb),
    (76, '{"type": "mcq_single", "prompt": "Как сказать «Я никогда не ем овощи»?", "choices": [{"id": "a", "text": "Nunca como verduras."}, {"id": "b", "text": "No nunca como verduras."}, {"id": "c", "text": "Nunca come verduras."}, {"id": "d", "text": "Nunca no como verduras."}], "correct_answer": "a", "explanation": "Como — форма первого лица. В начале предложения nunca уже означает «никогда», поэтому перед como не нужно добавлять no.", "theory_block_id": "b4_theory_frequency_nunca", "chapter_id": "es.grammar.present_regular_actions.frequency_expressions_siempre_menudo_veces_nunca", "concept_id": "present_frequency_nunca_adverb", "difficulty": 2, "id": "es.grammar.present_regular_actions.frequency_expressions_siempre_menudo_veces_nunca::b4_theory_frequency_nunca::q5", "signature": "5c33a7f04e2df21a"}'::jsonb)
)
SELECT 74 AS report_id, EXISTS (
  SELECT 1 FROM reading_texts t
  CROSS JOIN LATERAL jsonb_array_elements(t.reading_passage::jsonb->'segments') s(segment)
  WHERE t.text_id = 'free_es_a2_el_cuaderno_de_in_s_1782923708' AND s.segment = '{"audio_rel_path": "assets/reading/free_es_a2_el_cuaderno_de_in_s_1782923708/seg_06_speaker_a_v2.mp3", "segment_id": "s6", "speaker_id": "speaker_a", "text": "Me gusta mirar ese dibujo. Me ayuda a relajarme.", "text_translation_ru": "Мне нравится смотреть на этот рисунок. Он помогает мне расслабиться.", "tokens": [{"surface": "Me", "lemma": "me", "clickable": true, "token_idx": 0}, {"surface": "gusta", "lemma": "gusta", "clickable": true, "token_idx": 1}, {"surface": "mirar", "lemma": "mirar", "clickable": true, "token_idx": 2}, {"surface": "ese", "lemma": "ese", "clickable": true, "token_idx": 3}, {"surface": "dibujo", "lemma": "dibujo", "clickable": true, "token_idx": 4}, {"surface": ".", "lemma": ".", "clickable": false, "token_idx": 5}, {"surface": "Me", "lemma": "me", "clickable": true, "token_idx": 6}, {"surface": "ayuda", "lemma": "ayuda", "clickable": true, "token_idx": 7}, {"surface": "a", "lemma": "a", "clickable": true, "token_idx": 8}, {"surface": "relajarme", "lemma": "relajarme", "clickable": true, "token_idx": 9}, {"surface": ".", "lemma": ".", "clickable": false, "token_idx": 10}], "voice_id": "es_AR_daniela_high"}'::jsonb
) AS matches_expected
UNION ALL
SELECT e.report_id, COALESCE(q.raw_json::jsonb = e.question, false)
FROM expected e LEFT JOIN grammar_training_content_questions q
  ON q.bundle_id = 'es' AND q.question_id = (e.question->>'id')
ORDER BY report_id;
